def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    background = counts.most_common(1)[0][0]
    colors = [c for c in counts if c != background]
    if not colors:
        return [row[:] for row in grid]
    # The rare non-background, nonzero color is the template object.
    color = min(colors, key=lambda c: counts[c])
    pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
    # Use the largest 4-connected component if the object has multiple parts.
    components = []
    unseen = set(pts)
    while unseen:
        seed = unseen.pop()
        comp = {seed}
        q = [seed]
        while q:
            r, c = q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen:
                    unseen.remove(p); comp.add(p); q.append(p)
        components.append(comp)
    shape = max(components, key=len)
    minr = min(r for r,c in shape); minc = min(c for r,c in shape)
    shape = {(r-minr,c-minc) for r,c in shape}
    sh, sw = max(r for r,c in shape)+1, max(c for r,c in shape)+1
    out = [row[:] for row in grid]
    for r0 in range(h-sh+1):
        for c0 in range(w-sw+1):
            if all(grid[r0+r][c0+c] == 0 for r,c in shape):
